QString listText(const QJsonValue&v){QStringList a;for(auto x:v.toArray())a<<x.toString();return a.join(", ");}
QPushButton*button(QString text,std::function<void()>fn,QWidget*parent=nullptr){auto*b=new QPushButton(text,parent);b->setCursor(Qt::PointingHandCursor);QObject::connect(b,&QPushButton::clicked,b,fn);return b;}
