void OmadashWindow::refreshInbox(){int old=inbox->currentRow();QString error;rows=store.visible(account,split,live&&view=="search"?"all":view,live?QString():query,&error);if(live&&view=="search"){rows.clear();for(int i=0;i<store.threads.size();++i)rows<<i;}searchError->setText(error);QSignalBlocker block(tabs);while(tabs->count())tabs->removeTab(0);for(auto v:store.splits){auto s=v.toObject();int n=store.visible(account,s["id"].toString(),"inbox","").size();int i=tabs->addTab(s["name"].toString()+"  "+QString::number(n));tabs->setTabData(i,s["id"].toString());if(s["id"]==split)tabs->setCurrentIndex(i);}inbox->clear();QDate previous;for(int index:rows){auto t=store.threads[index].toObject();auto*item=new QListWidgetItem(t["sender"].toString()+" — "+t["subject"].toString(),inbox);item->setData(Qt::UserRole,index);item->setData(Qt::UserRole+1,t);QDate day=QDateTime::fromString(t["date"].toString(),Qt::ISODate).toLocalTime().date();if(!day.isValid())day=QDate::fromString(t["date"].toString(),Qt::ISODate);if(day.isValid()&&day!=previous&&day!=QDate::currentDate()){item->setData(Qt::UserRole+2,day==QDate::currentDate().addDays(-1)?"Yesterday":day.toString("MMMM d"));}previous=day;item->setToolTip(t["subject"].toString());}if(!rows.isEmpty())inbox->setCurrentRow(qBound(0,old,rows.size()-1));heading->setText(view=="inbox"?"Inbox":view=="search"?"Search results":view=="archive"?"Archived":view=="all"?"All mail":view=="starred"?"Starred":"Trash");count->setText(QString::number(rows.size())+" conversations"+(view=="search"?" · Entire sample history, including archived mail":""));searchBar->setVisible(view=="search");if(live){count->setText(QString::number(rows.size())+" loaded conversations · "+(loading?"Loading…":pageToken.isEmpty()?"End of results":"More available")+(google&&google->canModify()?" · Gmail actions enabled":" · Read-only"));moreButton->setVisible(!pageToken.isEmpty());moreButton->setEnabled(!loading);}}
void OmadashWindow::switchSplit(int i){if(i<0)return;bool reload=live&&view!="inbox";split=tabs->tabData(i).toString();view="inbox";threadIndex=-1;pages->setCurrentIndex(0);inbox->setCurrentRow(0);refreshInbox();if(reload)loadGoogle();inbox->setFocus();}
OmadashWindow::Context OmadashWindow::context()const{return {pages->currentIndex(),threadIndex,messageIndex,inbox->currentRow(),view,query,draftId};}
void OmadashWindow::restore(const Context&c){threadIndex=c.thread;messageIndex=c.message;view=c.view;query=c.query;draftId=c.draft;searchInput->setText(query);refreshInbox();inbox->setCurrentRow(c.row);if(c.page==1)buildReader();else if(c.page==2){clearLayout(composeLayout);auto*backRow=new QHBoxLayout;backRow->addWidget(button("← Back  Esc",[this]{back();}));backRow->addStretch();backRow->addWidget(button("Search mail  /",[this]{search();}));composeLayout->addLayout(backRow);composeLayout->addWidget(composer(),1);pages->setCurrentIndex(2);}else pages->setCurrentIndex(0);}
void OmadashWindow::openThread(int index){++attachmentGeneration;if(index<0||index>=store.threads.size())return;persistDraft();threadIndex=index;auto t=store.threads[index].toObject();if(!live)t["unread"]=false;store.threads[index]=t;messageIndex=t["messages"].toArray().size()-1;expanded={messageIndex};headers.clear();draftId.clear();buildReader();pages->setCurrentIndex(1);selectMessage(messageIndex);save();}
