QWidget*OmadashWindow::composer(){filling=true;auto d=store.drafts[draftId].toObject();auto*w=new QWidget;auto*l=new QVBoxLayout(w);l->setContentsMargins(20,20,20,20);auto*form=new QFormLayout;fromEdit=new QComboBox;fromEdit->setObjectName("draftFrom");for(auto v:store.accounts){auto a=v.toObject();fromEdit->addItem(a["email"].toString(),a["id"].toString());}int ai=fromEdit->findData(d["account"].toString());if(ai>=0)fromEdit->setCurrentIndex(ai);if(live)fromEdit->setEnabled(false);form->addRow("From",fromEdit);auto field=[&](QString key,QString title){auto*e=new QLineEdit(d[key].toString());e->setObjectName("draft"+title);form->addRow(title,e);connect(e,&QLineEdit::textChanged,this,[this]{persistDraft();saveTimer->start(250);});return e;};toEdit=field("to","To");ccEdit=field("cc","Cc");bccEdit=field("bcc","Bcc");subjectEdit=field("subject","Subject");l->addLayout(form);if(d["sourceMessage"].toInt(-1)>=0)l->addWidget(label("Replying to message "+QString::number(d["sourceMessage"].toInt()+1),"replyTarget"));bodyEdit=new QTextEdit;bodyEdit->setObjectName("draftBody");bodyEdit->setAcceptRichText(false);bodyEdit->setPlainText(d["body"].toString());bodyEdit->setMinimumHeight(170);l->addWidget(bodyEdit,1);connect(bodyEdit,&QTextEdit::textChanged,this,[this]{persistDraft();saveTimer->start(250);});connect(fromEdit,&QComboBox::currentIndexChanged,this,[this]{persistDraft();saveTimer->start(250);});auto*row=new QHBoxLayout;auto*send=button(live?"Send  Ctrl Enter":"Simulate send  Ctrl Enter",[this]{finishDraft(true);});send->setObjectName("sendButton");row->addWidget(send);if(live)row->addWidget(button("Attach files…",[this]{addDraftAttachments();}));row->addWidget(button("Save & close",[this]{back();}));row->addStretch();row->addWidget(button("Discard",[this]{finishDraft(false);}));l->addLayout(row);l->addWidget(label(live?"Draft saved locally · Automatically syncs to Gmail":"Sample draft · Nothing will be emailed","muted"));for(int i=0;i<d["attachments"].toArray().size();++i){auto file=d["attachments"].toArray()[i].toObject();l->addWidget(button("×  "+file["name"].toString(),[this,i]{persistDraft();auto d=store.drafts[draftId].toObject();auto files=d["attachments"].toArray();files.removeAt(i);d["attachments"]=files;store.drafts[draftId]=d;openLiveDraft(draftId);}));}if(live&&d["uncertain"].toBool()){l->addWidget(label("Last request was not confirmed. Check Gmail Drafts and Sent before retrying."));l->addWidget(button("I checked Gmail — allow another attempt",[this]{auto d=store.drafts[draftId].toObject();d["uncertain"]=false;store.drafts[draftId]=d;saveLocalDrafts();notify("You can now save or send this draft again.");}));}filling=false;return w;}
void OmadashWindow::persistDraft(){if(filling||draftId.isEmpty()||!bodyEdit||!toEdit)return;auto d=store.drafts[draftId].toObject();d["to"]=toEdit->text();d["cc"]=ccEdit->text();d["bcc"]=bccEdit->text();d["subject"]=subjectEdit->text();d["body"]=bodyEdit->toPlainText();d["account"]=fromEdit->currentData().toString();store.drafts[draftId]=d;if(live&&cache&&!cache->putDraft(draftId,d))notify("Draft could not be saved locally: "+cache->error);}
void OmadashWindow::compose(const QString&mode){if(live&&!google->canModify()){drawer("Enable Gmail actions to compose and send.",{{"Enable Gmail actions…","enable"}},[this](QString){connectGoogle(true);});return;}persistDraft();navigation<<context();bodyEdit=nullptr;toEdit=nullptr;if(mode=="compose"){draftId=live?QUuid::createUuid().toString(QUuid::WithoutBraces):"new";if(!store.drafts.contains(draftId))store.drafts[draftId]=QJsonObject{{"account",account=="all"?"work":account},{"mode",mode},{"sourceThread",-1},{"sourceMessage",-1}};clearLayout(composeLayout);auto*bar=new QHBoxLayout;bar->addWidget(button("← Back",[this]{back();}));bar->addWidget(label("New message","heading"));bar->addStretch();bar->addWidget(button("Search /",[this]{search();}));composeLayout->addLayout(bar);composeLayout->addWidget(composer(),1);pages->setCurrentIndex(2);}else{if(pages->currentIndex()==0){if(!inbox->currentItem())return;threadIndex=inbox->currentItem()->data(Qt::UserRole).toInt();messageIndex=store.threads[threadIndex].toObject()["messages"].toArray().size()-1;}draftId=live?QUuid::createUuid().toString(QUuid::WithoutBraces):QString("%1:%2:%3").arg(threadIndex).arg(messageIndex).arg(mode);if(!store.drafts.contains(draftId)){auto d=store.replyDraft(threadIndex,messageIndex,mode);if(live&&mode=="forward")d["body"]=d["body"].toString().replace("Forwarded sample message","Forwarded message");d["threadId"]=store.threads[threadIndex].toObject()["id"];store.drafts[draftId]=d;}expanded.insert(messageIndex);buildReader();}bodyEdit->setFocus();save();}
void OmadashWindow::finishDraft(bool send){persistDraft();if(live){QString id=draftId;if(id.isEmpty()||draftJobs.contains(id))return;if(send){syncDraft(id,true);return;}auto d=store.drafts[id].toObject();auto remove=[this,id]{store.drafts.remove(id);cache->removeDraft(id);draftId.clear();bodyEdit=nullptr;toEdit=nullptr;pages->setCurrentIndex(0);refreshCached(account);notify("Draft discarded.");};if(d["gmailDraftId"].toString().isEmpty())remove();else if(sessions.contains(d["account"].toString())){draftJobs.insert(id);sessions[d["account"].toString()].client->mutate("DELETE","gmail/v1/users/me/drafts/"+d["gmailDraftId"].toString(),{},[this,id,remove](QJsonObject,QString error){draftJobs.remove(id);if(error.isEmpty())remove();else notify(error);});}return;}if(send&&toEdit->text().trimmed().isEmpty()){notify("Add a recipient first.");toEdit->setFocus();return;}store.drafts.remove(draftId);draftId.clear();bodyEdit=nullptr;toEdit=nullptr;back();save();notify(send?"Send simulated. No email was sent.":"Draft discarded.");}
void OmadashWindow::search(){persistDraft();if(!live)navigation<<context();bodyEdit=nullptr;toEdit=nullptr;view="search";query.clear();searchInput->clear();pages->setCurrentIndex(0);refreshInbox();if(live){query.clear();loadGoogle();}searchInput->setFocus();}
void OmadashWindow::back(){++attachmentGeneration;if(attachmentPage&&pages->currentWidget()==attachmentPage){++attachmentGeneration;clearLayout(attachmentLayout);pages->setCurrentIndex(1);selectMessage(messageIndex);return;}if(live){if(!draftId.isEmpty()){persistDraft();saveLocalDrafts();syncDraft(draftId);draftId.clear();bodyEdit=nullptr;toEdit=nullptr;}if(pages->currentIndex()==1||pages->currentIndex()==2){pages->setCurrentIndex(0);refreshCached(account);inbox->setFocus();return;}if(view=="search"){view="inbox";query.clear();navigation.clear();loadGoogle();return;}return;}bool wasSearch=live&&view=="search"&&pages->currentIndex()==0;persistDraft();save();bodyEdit=nullptr;toEdit=nullptr;draftId.clear();if(!navigation.isEmpty()){auto c=navigation.takeLast();restore(c);}else{pages->setCurrentIndex(0);refreshInbox();inbox->setFocus();}if(wasSearch){view="inbox";query.clear();loadGoogle();}}
void OmadashWindow::save(){if(live){persistDraft();saveLocalDrafts();if(cloudDraftTimer&&!draftId.isEmpty())cloudDraftTimer->start();return;}persistDraft();if(!store.save())notify("Could not save sample workspace: "+store.saveError);}
void OmadashWindow::notify(const QString&s){status->setText(s);}
