void OmadashWindow::toggleCalendar(){calendarVisible=!calendarVisible;if(calendarVisible)buildCalendar();calendar->setVisible(calendarVisible);}
void OmadashWindow::buildCalendar(){if(live){loadCalendar();return;}clearLayout(calendarLayout);calendarLayout->addWidget(label("Calendar","heading"));calendarLayout->addWidget(label("Sample schedule · All accounts","muted"));auto*row=new QHBoxLayout;row->addWidget(button("‹",[this]{calendarDate=calendarDate.addDays(-1);buildCalendar();}));row->addWidget(button("Today",[this]{calendarDate=QDate(2026,9,14);buildCalendar();}));row->addWidget(button("›",[this]{calendarDate=calendarDate.addDays(1);buildCalendar();}));calendarLayout->addLayout(row);calendarLayout->addWidget(label(calendarDate.toString("dddd, MMMM d")));calendarLayout->addSpacing(25);if(calendarDate==QDate(2026,9,14)){for(auto pair:QList<QPair<QString,QString>>{{"09:30 — 10:00","Product sync"},{"11:00 — 11:45","Design review"},{"14:00 — 14:30","Customer conversation"}}){calendarLayout->addWidget(label(pair.first,"muted"));calendarLayout->addWidget(label(pair.second));calendarLayout->addSpacing(25);}}else calendarLayout->addWidget(label("No sample events"));calendarLayout->addStretch();calendarLayout->addWidget(label("Google Calendar is not connected.","muted"));}
void OmadashWindow::change(const QString&a){if(live){liveAction(a);return;}QVector<int> ids;if(pages->currentIndex()==1)ids<<threadIndex;else for(auto*i:inbox->selectedItems())ids<<i->data(Qt::UserRole).toInt();store.change(ids,a);if(pages->currentIndex()==1)back();refreshInbox();save();notify("Sample mail updated · Z to undo");}
void OmadashWindow::drawer(const QString&title,const QList<QPair<QString,QString>>&entries,std::function<void(QString)>fn){clearLayout(commandLayout);commandLayout->addWidget(label(title));auto*input=new QLineEdit;input->setPlaceholderText("Type to filter · Esc to close");auto*list=new QListWidget;list->setMaximumHeight(220);for(auto [name,id]:entries){auto*i=new QListWidgetItem(name,list);i->setData(Qt::UserRole,id);}commandLayout->addWidget(input);commandLayout->addWidget(list);connect(input,&QLineEdit::textChanged,list,[list](QString s){for(int i=0;i<list->count();++i)list->item(i)->setHidden(!list->item(i)->text().contains(s,Qt::CaseInsensitive));});auto run=[this,fn](QListWidgetItem*i){if(!i)return;auto id=i->data(Qt::UserRole).toString();hideDrawer();fn(id);};connect(list,&QListWidget::itemActivated,this,run);connect(list,&QListWidget::itemClicked,this,run);connect(input,&QLineEdit::returnPressed,list,[list,run]{for(int i=0;i<list->count();++i)if(!list->item(i)->isHidden()){run(list->item(i));break;}});commandPanel->show();input->setFocus();}
void OmadashWindow::hideDrawer(){commandPanel->hide();if(pages->currentIndex()==0)inbox->setFocus();}
void OmadashWindow::showCommands(){drawer("Commands",{{"Compose · C","compose"},{"Search · /","search"},{"Calendar · 0","calendar"},{"Archive · E","archive"},{"Accounts","accounts"},{"Manage splits","splits"}},[this](QString s){if(s=="compose")compose();else if(s=="search")search();else if(s=="calendar")toggleCalendar();else if(s=="accounts")accounts();else if(s=="splits")splits();else change(s);});}
void OmadashWindow::showFolders(){drawer("Go to",{{"Inbox","inbox"},{"All mail","all"},{"Archive","archive"},{"Starred","starred"},{"Trash","trash"}},[this](QString s){persistDraft();bodyEdit=nullptr;toEdit=nullptr;draftId.clear();view=s;query.clear();pages->setCurrentIndex(0);refreshInbox();if(live)loadGoogle();});}
void OmadashWindow::showDrafts(){persistDraft();if(live)saveLocalDrafts();QList<QPair<QString,QString>> list;for(auto i=store.drafts.begin();i!=store.drafts.end();++i)if(!live||i.value().toObject()["account"]==account)list<<qMakePair(i.value().toObject()["subject"].toString("Untitled draft"),i.key());drawer(list.isEmpty()?"No saved drafts":"Drafts",list,[this](QString id){if(live){openLiveDraft(id);return;}navigation<<context();auto d=store.drafts[id].toObject();Context c{d["sourceThread"].toInt(-1)<0?2:1,d["sourceThread"].toInt(-1),d["sourceMessage"].toInt(0),inbox->currentRow(),view,query,id};bodyEdit=nullptr;toEdit=nullptr;restore(c);});}
void OmadashWindow::showLabels(){notify("Label editing is coming in the next native preview.");}
void OmadashWindow::updateAccount(){QSignalBlocker blocker(accountTabs);while(accountTabs->count())accountTabs->removeTab(0);if(live)for(auto id:accountOrder){int i=accountTabs->addTab(store.accountEmail(id));accountTabs->setTabData(i,id);if(id==account)accountTabs->setCurrentIndex(i);}accountTabs->setVisible(live);accountButton->setText(account=="all"?"All accounts  ⌄":store.accountEmail(account));refreshInbox();}
void OmadashWindow::accounts(){QDialog d(this);d.setWindowTitle("Accounts");auto*l=new QVBoxLayout(&d);l->addWidget(label("Google accounts","heading"));if(live){for(int i=0;i<accountOrder.size();++i){QString id=accountOrder[i];auto*b=button((id==account?"●  ":"")+id+"   Alt+"+QString::number(i+1),[&,id]{d.accept();switchAccount(id);});l->addWidget(b);auto*images=new QCheckBox("Automatically load external images");images->setChecked(externalImages.value(id,false));images->setToolTip("External images contact the sender’s servers and may reveal that you opened an email.");connect(images,&QCheckBox::toggled,this,[this,id](bool enabled){setAccountImages(id,enabled);});l->addWidget(images);}l->addWidget(button(google->canModify()?"Reconnect current account permissions":"Enable Gmail actions",[&]{d.accept();connectGoogle(true,true);}));l->addWidget(button("Add Google account",[&]{d.accept();connectGoogle();}));l->addWidget(button("Refresh current account",[&]{d.accept();loadGoogle();if(calendarVisible)buildCalendar();}));l->addWidget(button("Disconnect "+account,[&]{d.accept();leaveGoogle();}));l->addWidget(label("Accounts are remembered in your Linux keyring.\nMail and drafts are cached privately on this computer.","muted"));}else{l->addWidget(button("Connect Google account",[&]{d.accept();connectGoogle();}));l->addWidget(button("Google app setup…",[&]{d.accept();googleSetup();}));for(auto v:store.accounts){auto a=v.toObject();l->addWidget(button(a["email"].toString(),[&,a]{account=a["id"].toString();d.accept();}));}}if(pendingGoogle)l->addWidget(button("Cancel pending sign-in",[&]{auto*c=pendingGoogle;pendingGoogle=nullptr;c->disconnectAccount();c->deleteLater();signInControls->hide();d.accept();}));d.exec();updateAccount();}
void OmadashWindow::splits(){if(live){notify("Split editing remains available in the sample workspace. Live split rules are fixed for this milestone.");return;}QDialog d(this);d.setWindowTitle("Manage splits");d.resize(590,360);auto*l=new QVBoxLayout(&d);l->addWidget(label("First matching split wins; Other catches the rest.","muted"));auto*table=new QTableWidget(store.splits.size(),2);table->setHorizontalHeaderLabels({"Name","Search rule"});table->horizontalHeader()->setSectionResizeMode(QHeaderView::Stretch);for(int i=0;i<store.splits.size();++i){auto s=store.splits[i].toObject();table->setItem(i,0,new QTableWidgetItem(s["name"].toString()));table->setItem(i,1,new QTableWidgetItem(s["rule"].toString()));if(s["id"]=="other")for(int c=0;c<2;++c)table->item(i,c)->setFlags(Qt::ItemIsEnabled);}l->addWidget(table);l->addWidget(button("Save",[&]{for(int i=0;i<store.splits.size();++i){auto s=store.splits[i].toObject();if(s["id"]=="other")continue;QString error;store.matches(store.threads.first().toObject(),table->item(i,1)->text(),&error);if(!error.isEmpty()){notify(error);return;}s["name"]=table->item(i,0)->text();s["rule"]=table->item(i,1)->text();store.splits[i]=s;}save();d.accept();}));d.exec();refreshInbox();}
bool OmadashWindow::eventFilter(QObject*o,QEvent*event){if(event->type()!=QEvent::KeyPress||QApplication::activeModalWidget())return false;auto*w=qobject_cast<QWidget*>(o);if(!w||w->window()!=this)return false;auto*k=static_cast<QKeyEvent*>(event);int key=k->key();auto mods=k->modifiers();bool editing=qobject_cast<QLineEdit*>(w)||qobject_cast<QTextEdit*>(w)||qobject_cast<QPlainTextEdit*>(w)||qobject_cast<QComboBox*>(w);if(mods==Qt::ControlModifier&&key==Qt::Key_K){showCommands();return true;}if(key==Qt::Key_Escape){if(commandPanel->isVisible())hideDrawer();else back();return true;}if(attachmentPage&&pages->currentWidget()==attachmentPage)return false;if(!draftId.isEmpty()&&bodyEdit&&mods==(Qt::ControlModifier|Qt::ShiftModifier)){QWidget*target=nullptr;if(key==Qt::Key_O)target=toEdit;else if(key==Qt::Key_C)target=ccEdit;else if(key==Qt::Key_B)target=bccEdit;else if(key==Qt::Key_F)target=fromEdit;else if(key==Qt::Key_S)target=subjectEdit;else if(key==Qt::Key_M)target=bodyEdit;if(target){target->setFocus();return true;}}if(o==searchInput&&mods==Qt::NoModifier&&(key==Qt::Key_Return||key==Qt::Key_Enter)){executeSearch();return true;}if(editing){if(mods==Qt::ControlModifier&&(key==Qt::Key_Return||key==Qt::Key_Enter)&&!draftId.isEmpty()){finishDraft(true);return true;}return false;}if(live&&mods==Qt::AltModifier&&key>=Qt::Key_1&&key<=Qt::Key_9){int i=key-Qt::Key_1;if(i<accountOrder.size())switchAccount(accountOrder[i]);return true;}if(!live&&mods==Qt::AltModifier&&key>=Qt::Key_1&&key<=Qt::Key_2){account=store.accounts[key-Qt::Key_1].toObject()["id"].toString();updateAccount();return true;}if(mods!=Qt::NoModifier&&mods!=Qt::ShiftModifier)return false;if(sequence=="g"){sequence.clear();QString dest;if(key==Qt::Key_I)dest="inbox";else if(key==Qt::Key_A)dest="all";else if(key==Qt::Key_E)dest="archive";else if(key==Qt::Key_D){showDrafts();return true;}else if(key==Qt::Key_O){dest="inbox";split="other";}if(!dest.isEmpty()){view=dest;pages->setCurrentIndex(0);refreshInbox();if(live)loadGoogle();inbox->setFocus();return true;}}if(key==Qt::Key_G){sequence="g";QTimer::singleShot(1200,this,[this]{sequence.clear();});return true;}if(key==Qt::Key_Slash){search();return true;}if(key==Qt::Key_0){toggleCalendar();return true;}if(key==Qt::Key_C){compose();return true;}if(key==Qt::Key_Z){if(live){undoGmail();return true;}store.undo();refreshInbox();save();return true;}if(key==Qt::Key_E){change(mods==Qt::ShiftModifier?"restore":"archive");return true;}if(key==Qt::Key_NumberSign){change("trash");return true;}if(key==Qt::Key_U){markUnread();return true;}if(key==Qt::Key_S){change("star");return true;}if(key==Qt::Key_L){showLabels();return true;}if(pages->currentIndex()==0){if(key==Qt::Key_Tab||key==Qt::Key_Backtab){int delta=key==Qt::Key_Backtab?-1:1;tabs->setCurrentIndex((tabs->currentIndex()+delta+tabs->count())%tabs->count());return true;}if(key==Qt::Key_J||key==Qt::Key_K){inbox->setCurrentRow(qBound(0,inbox->currentRow()+(key==Qt::Key_J?1:-1),inbox->count()-1));return true;}if(key==Qt::Key_Return||key==Qt::Key_Enter){if(inbox->currentItem())openThread(inbox->currentItem()->data(Qt::UserRole).toInt());return true;}}if(pages->currentIndex()==1){if(key==Qt::Key_Up||key==Qt::Key_K||key==Qt::Key_P){selectMessage(messageIndex-1);return true;}if(key==Qt::Key_Down||key==Qt::Key_J||key==Qt::Key_N){selectMessage(messageIndex+1);return true;}if(key==Qt::Key_Return||key==Qt::Key_Enter){compose("reply-all");return true;}if(key==Qt::Key_R||key==Qt::Key_F){compose(key==Qt::Key_R?"reply":"forward");return true;}if(key==Qt::Key_O){if(expanded.contains(messageIndex))expanded.remove(messageIndex);else expanded.insert(messageIndex);buildReader();selectMessage(messageIndex);return true;}}return false;}
void OmadashWindow::googleSetup(){QDialog d(this);d.setWindowTitle("Connect Omadash to Google");d.resize(620,410);auto*l=new QVBoxLayout(&d);l->addWidget(label("Google app setup","heading"));auto*text=label("1. Create a Google Cloud project named Omadash.\n\n2. Enable Gmail API and Google Calendar API.\n\n3. Configure Google Auth Platform: External audience, Testing mode, and add your Google email as a test user.\n\n4. Create an OAuth client with application type Desktop app. Download its JSON file.\n\n5. Import that file here, then connect your Google account.\n\nConnect with Gmail actions to triage, save drafts, and send. Login credentials are stored in the Linux keyring.");text->setWordWrap(true);l->addWidget(text);l->addWidget(button("Open Google Cloud Console",[]{QDesktopServices::openUrl(QUrl("https://console.cloud.google.com/projectcreate"));}));l->addWidget(button("Import Desktop client JSON…",[&]{QString path=QFileDialog::getOpenFileName(&d,"Google Desktop client JSON",QDir::homePath()+"/Downloads","JSON files (*.json)");if(path.isEmpty())return;QFile f(path);if(!f.open(QIODevice::ReadOnly)||f.size()>65536){notify("Could not read that client JSON file.");return;}QByteArray json=f.readAll();QString error;if(!google->configure(json,&error)){notify(error);return;}QString dir=QCoreApplication::applicationDirPath()+"/../.state";QDir().mkpath(dir);QSaveFile out(dir+"/google-client.json");if(!out.open(QIODevice::WriteOnly)){notify("Could not save the app configuration.");return;}if(!out.setPermissions(QFile::ReadOwner|QFile::WriteOwner)){notify("Could not restrict access to the app configuration.");return;}if(out.write(json)!=json.size()||!out.commit()){notify("Could not finish saving the app configuration.");return;}notify("Google app configured. Choose Connect Google account.");d.accept();}));l->addWidget(button("Close",[&]{d.reject();}));d.exec();}
GoogleClient*OmadashWindow::makeGoogleClient(){auto*c=new GoogleClient(this);connect(c,&GoogleClient::signInReady,this,[this](QUrl){signInControls->show();});connect(c,&GoogleClient::progress,this,&OmadashWindow::notify);connect(c,&GoogleClient::problem,this,[this,c](QString error){notify(error);if(pendingGoogle==c){signInControls->hide();pendingGoogle=nullptr;c->disconnectAccount();c->deleteLater();}});connect(c,&GoogleClient::authorized,this,&OmadashWindow::enterGoogle);return c;}
void OmadashWindow::connectGoogle(bool modify,bool current){if(actionBusy||!draftJobs.isEmpty()){notify("Wait for the current Gmail action to finish before reconnecting.");return;}if(pendingGoogle){notify("Finish the Google sign-in already open, or cancel it from Accounts.");return;}QFile f(QCoreApplication::applicationDirPath()+"/../.state/google-client.json");if(!f.open(QIODevice::ReadOnly)){googleSetup();return;}auto*c=makeGoogleClient();QString error;if(!c->configure(f.readAll(),&error)){c->deleteLater();notify(error);return;}pendingGoogle=c;c->authorize(modify,live&&(current||(modify&&!google->canModify()))?account:QString());}
void OmadashWindow::enterGoogle(){auto*c=qobject_cast<GoogleClient*>(sender());if(!c||pendingGoogle!=c)return;signInControls->hide();notify("Loading Google account identity…");c->get("gmail/v1/users/me/profile",{},[this,c](QJsonObject profile,QString error){if(pendingGoogle!=c)return;QString address=profile["emailAddress"].toString().trimmed().toLower();if(!error.isEmpty()||address.isEmpty()){pendingGoogle=nullptr;c->disconnectAccount();c->deleteLater();notify(error.isEmpty()?"Google did not return an account identity.":error);return;}pendingGoogle=nullptr;registerAccount(address,c);});}
void OmadashWindow::cacheAccount(){if(!live||!sessions.contains(account))return;auto &s=sessions[account];s.threads=store.threads;for(int i=0;i<s.threads.size();++i){auto t=s.threads[i].toObject();auto msgs=t["messages"].toArray();for(int j=0;j<msgs.size();++j){auto m=msgs[j].toObject();if(!m["assetsComplete"].toBool())m["assetsStarted"]=false;msgs[j]=m;}t["messages"]=msgs;s.threads[i]=t;}s.split=split;s.view=view;s.query=query;s.page=pageToken;s.row=inbox->currentRow();s.loaded=!loading&&!s.stale;}
void OmadashWindow::registerAccount(const QString&address,GoogleClient*c,bool fetch){cacheAccount();if(!live){save();sampleAccounts=store.accounts;sampleThreads=store.threads;sampleSplits=store.splits;sampleDrafts=store.drafts;live=true;store.setSessionOnly(true);store.accounts={};store.drafts=cache?cache->drafts():QJsonObject();store.splits=MailStore(false).splits;calendarDate=QDate::currentDate();}if(sessions.contains(address)){auto*old=sessions[address].client;if(old!=c){if(syncs.contains(address))delete syncs.take(address);old->disconnectAccount();old->deleteLater();}sessions[address].client=c;}else{sessions[address].client=c;if(cache){sessions[address].threads=cache->threads(address);sessions[address].loaded=!sessions[address].threads.isEmpty();}accountOrder<<address;store.accounts.append(QJsonObject{{"id",address},{"email",address}});}if(cache){auto saved=cache->drafts();for(auto id:saved.keys())if(saved[id].toObject()["account"]==address&&!store.drafts.contains(id))store.drafts[id]=saved[id];}switchAccount(address,fetch);if(fetch){rememberAccount(address,c);startSync(address);}notify("Connected "+address+(c->canModify()?" · Gmail actions enabled":" · Read-only"));}
void OmadashWindow::switchAccount(const QString&id,bool fetch){if(!sessions.contains(id))return;if(live){persistDraft();saveLocalDrafts();}cacheAccount();++mailGeneration;++calendarGeneration;++attachmentGeneration;auto &s=sessions[id];account=id;liveEmail=id;google=s.client;store.threads=s.threads;split=s.split;view=s.view;query=s.query;pageToken=s.page;loading=false;navigation.clear();draftId.clear();bodyEdit=nullptr;toEdit=nullptr;threadIndex=-1;clearLayout(threadLayout);clearLayout(composeLayout);if(attachmentLayout)clearLayout(attachmentLayout);pages->setCurrentIndex(0);searchInput->setText(query);searchInput->setPlaceholderText("Search "+id+" — all Gmail history");updateAccount();inbox->setCurrentRow(qBound(0,s.row,inbox->count()-1));inbox->setFocus();if(fetch&&!s.loaded)loadGoogle();if(fetch&&calendarVisible)buildCalendar();}
void OmadashWindow::leaveGoogle(){if(!live)return;if(actionBusy||!draftJobs.isEmpty()){notify("Wait for the current Gmail action to finish before disconnecting.");return;}QString removed=account;if(syncs.contains(removed)){delete syncs.take(removed);}if(cache)cache->forget(removed);if(persistPreferences)keyring->remove(removed,[this](QByteArray,QString e){if(!e.isEmpty())notify("Account removed from Omadash; keyring cleanup failed. Remove its Omadash entry in your password manager.");});for(auto id:store.drafts.keys())if(store.drafts[id].toObject()["account"]==removed)store.drafts.remove(id);auto*c=sessions.value(removed).client;if(c){c->disconnectAccount();c->deleteLater();}sessions.remove(removed);accountOrder.removeAll(removed);for(int i=store.accounts.size()-1;i>=0;--i)if(store.accounts[i].toObject()["id"]==removed)store.accounts.removeAt(i);++mailGeneration;++calendarGeneration;++attachmentGeneration;if(!sessions.isEmpty()){switchAccount(accountOrder.first());notify("Disconnected "+removed);return;}google=makeGoogleClient();live=false;loading=false;store.setSessionOnly(false);store.accounts=sampleAccounts;store.threads=sampleThreads;store.splits=sampleSplits;store.drafts=sampleDrafts;sampleAccounts={};sampleThreads={};sampleSplits={};sampleDrafts={};pageToken.clear();liveEmail.clear();calendarDate=QDate(2026,9,14);account="all";split="important";view="inbox";query.clear();navigation.clear();draftId.clear();threadIndex=-1;bodyEdit=nullptr;toEdit=nullptr;clearLayout(threadLayout);clearLayout(composeLayout);if(attachmentLayout)clearLayout(attachmentLayout);moreButton->hide();pages->setCurrentIndex(0);updateAccount();if(calendarVisible)buildCalendar();notify("Disconnected. Sample workspace restored.");}
void OmadashWindow::executeSearch(){view="search";threadIndex=-1;pages->setCurrentIndex(0);query=searchInput->text();if(live)loadGoogle();else refreshInbox();inbox->setFocus();}
void OmadashWindow::loadCalendar(){int gen=++calendarGeneration;clearLayout(calendarLayout);calendarLayout->addWidget(label("Calendar","heading"));calendarLayout->addWidget(label(liveEmail+" · Primary calendar","muted"));auto*nav=new QHBoxLayout;nav->addWidget(button("‹",[this]{calendarDate=calendarDate.addDays(-1);buildCalendar();}));nav->addWidget(button("Today",[this]{calendarDate=QDate::currentDate();buildCalendar();}));nav->addWidget(button("›",[this]{calendarDate=calendarDate.addDays(1);buildCalendar();}));calendarLayout->addLayout(nav);calendarLayout->addWidget(label(calendarDate.toString("dddd, MMMM d")));auto*scroll=new QScrollArea;scroll->setWidgetResizable(true);auto*body=new QWidget;auto*l=new QVBoxLayout(body);auto*message=label("Loading events…","muted");l->addWidget(message);l->addStretch();scroll->setWidget(body);calendarLayout->addWidget(scroll,1);QPointer<QVBoxLayout> target=l;QDateTime from(calendarDate,QTime(0,0),QTimeZone::systemTimeZone()),until(calendarDate.addDays(1),QTime(0,0),QTimeZone::systemTimeZone());auto step=std::make_shared<std::function<void(QString)>>();std::weak_ptr<std::function<void(QString)>> weak=step;*step=[this,gen,target,from,until,weak](QString page){auto keep=weak.lock();if(!keep||gen!=calendarGeneration||!live)return;google->get("calendar/v3/calendars/primary/events",{{"singleEvents","true"},{"orderBy","startTime"},{"timeMin",from.toString(Qt::ISODate)},{"timeMax",until.toString(Qt::ISODate)},{"maxResults","100"},{"pageToken",page}},[this,gen,target,keep,page](QJsonObject result,QString error){if(gen!=calendarGeneration||!live||!target)return;if(page.isEmpty())clearLayout(target);if(!error.isEmpty()){auto*e=label(error,"error");e->setWordWrap(true);target->addWidget(e);return;}for(auto v:result["items"].toArray()){auto e=v.toObject();if(e["status"]=="cancelled")continue;auto start=e["start"].toObject();QString time=start["dateTime"].toString();target->addWidget(label(time.isEmpty()?"All day":QDateTime::fromString(time,Qt::ISODate).toLocalTime().toString("HH:mm"),"muted"));auto*title=label(e["summary"].toString("Busy"));title->setTextFormat(Qt::PlainText);title->setWordWrap(true);target->addWidget(title);target->addSpacing(18);}QString next=result["nextPageToken"].toString();if(!next.isEmpty())(*keep)(next);else{if(target->count()==0)target->addWidget(label("No events for this day","muted"));target->addStretch();}});};(*step)("");}

void OmadashWindow::loadMessageAssets(int ti,int mi){auto t=store.threads[ti].toObject();auto messages=t["messages"].toArray();auto m=messages[mi].toObject();auto parts=m["assets"].toArray();if(parts.isEmpty()||m["assetsStarted"].toBool())return;m["assetsStarted"]=true;messages[mi]=m;t["messages"]=messages;store.threads[ti]=t;QString tid=t["id"].toString(),mid=m["id"].toString();int gen=mailGeneration;auto index=std::make_shared<int>(0),total=std::make_shared<int>(0);auto result=std::make_shared<QJsonObject>(m);auto loaded=std::make_shared<QJsonArray>();auto step=std::make_shared<std::function<void()>>();std::weak_ptr<std::function<void()>> weak=step;*step=[this,ti,mi,tid,mid,gen,parts,index,total,result,loaded,weak]{auto keep=weak.lock();if(!keep||!live||gen!=mailGeneration||ti>=store.threads.size()||store.threads[ti].toObject()["id"]!=tid)return;if(*index>=parts.size()||*index>=40){QString html=(*result)["html"].toString();for(auto v:*loaded){auto part=v.toObject();QString mime=part["mime"].toString(),cid=part["cid"].toString();if(mime.startsWith("image/")&&!cid.isEmpty()){QString uri="data:"+mime+";base64,"+QString::fromLatin1(QByteArray::fromBase64(part["data"].toString().toLatin1(),QByteArray::Base64UrlEncoding).toBase64());html.replace("cid:"+cid,uri,Qt::CaseInsensitive);}}(*result)["html"]=html;(*result)["assetsComplete"]=true;auto thread=store.threads[ti].toObject();auto msgs=thread["messages"].toArray();msgs[mi]=*result;thread["messages"]=msgs;store.threads[ti]=thread;if(threadIndex==ti&&pages->currentIndex()==1){int selected=messageIndex;buildReader();selectMessage(selected);}return;}auto part=parts[(*index)++].toObject();int size=part["size"].toInt();if(size>5*1024*1024||*total+size>20*1024*1024){(*keep)();return;}*total+=size;auto apply=[result,loaded,part](QString data){auto copy=part;copy["data"]=data;loaded->append(copy);if(part["mime"]=="text/html")(*result)["html"]=QString::fromUtf8(QByteArray::fromBase64(data.toLatin1(),QByteArray::Base64UrlEncoding));if(part["mime"]=="text/plain")(*result)["body"]=QString::fromUtf8(QByteArray::fromBase64(data.toLatin1(),QByteArray::Base64UrlEncoding));};if(!part["data"].toString().isEmpty()){apply(part["data"].toString());(*keep)();return;}google->get("gmail/v1/users/me/messages/"+QString::fromLatin1(QUrl::toPercentEncoding(mid))+"/attachments/"+QString::fromLatin1(QUrl::toPercentEncoding(part["attachmentId"].toString())),{},[this,gen,keep,apply](QJsonObject data,QString error){if(!live||gen!=mailGeneration)return;if(error.isEmpty())apply(data["data"].toString());else notify("Some embedded email content could not load. Reopen after refreshing Gmail to retry.");(*keep)();});};QTimer::singleShot(0,this,[step]{(*step)();});}

void OmadashWindow::saveAttachment(const QString&name,const QByteArray&bytes){QString path=QFileDialog::getSaveFileName(this,"Save attachment",QDir::homePath()+"/Downloads/"+Attachments::safeName(name));if(path.isEmpty())return;QString error;if(Attachments::save(path,bytes,&error))notify("Attachment saved to "+path);else notify(error);}
void OmadashWindow::attachment(int ti,int mi,const QJsonObject&a,bool download){if(ti<0||ti>=store.threads.size())return;auto thread=store.threads[ti].toObject();auto msgs=thread["messages"].toArray();if(mi<0||mi>=msgs.size())return;messageIndex=mi;QString mid=msgs[mi].toObject()["id"].toString(),name=a["name"].toString(),mime=a["mime"].toString();if(a["size"].toInteger()>50*1024*1024){notify("Attachments larger than 50 MB are not supported in this preview.");return;}int gen=++attachmentGeneration;QString owner=account;auto accept=[this,gen,owner,name,mime,download](QByteArray data){if(gen!=attachmentGeneration||owner!=account)return;if(data.size()>50*1024*1024){notify("Attachment exceeds the 50 MB limit.");return;}if(download)saveAttachment(name,data);else showAttachment(name,mime,data);};if(a.contains("data")&&(!a["data"].toString().isEmpty()||a["size"].toInteger()==0)){accept(QByteArray::fromBase64(a["data"].toString().toLatin1(),QByteArray::Base64UrlEncoding));return;}if(!live||a["id"].toString().isEmpty()){notify("This attachment has no downloadable content.");return;}auto*client=google;notify("Loading attachment from "+owner+"…");client->get("gmail/v1/users/me/messages/"+QString::fromLatin1(QUrl::toPercentEncoding(mid))+"/attachments/"+QString::fromLatin1(QUrl::toPercentEncoding(a["id"].toString())),{},[this,gen,owner,accept](QJsonObject result,QString error){if(gen!=attachmentGeneration||owner!=account)return;if(!error.isEmpty()){notify(error);return;}auto decoded=QByteArray::fromBase64Encoding(result["data"].toString().toLatin1(),QByteArray::Base64UrlEncoding|QByteArray::AbortOnBase64DecodingErrors);if(!decoded){notify("The attachment data could not be decoded.");return;}accept(decoded.decoded);});}
void OmadashWindow::showAttachment(const QString&name,const QString&mime,const QByteArray&bytes){if(!attachmentPage){attachmentPage=new QWidget;attachmentPage->setObjectName("attachmentPage");attachmentLayout=new QVBoxLayout(attachmentPage);pages->addWidget(attachmentPage);}clearLayout(attachmentLayout);auto*bar=new QHBoxLayout;bar->addWidget(button("← Back to message  Esc",[this]{back();}));bar->addWidget(label(name,"heading"),1);bar->addWidget(button("Save…",[this,name,bytes]{saveAttachment(name,bytes);}));attachmentLayout->addLayout(bar);if(mime=="application/pdf"||bytes.startsWith("%PDF-")){auto*pdf=new AttachmentPdfView;auto*doc=new QPdfDocument(pdf);auto*buffer=new QBuffer(doc);buffer->setData(bytes);buffer->open(QIODevice::ReadOnly);doc->load(buffer);pdf->setDocument(doc);pdf->setPageMode(QPdfView::PageMode::MultiPage);pdf->setZoomMode(QPdfView::ZoomMode::FitToWidth);attachmentLayout->addWidget(pdf,1);auto*error=label("");attachmentLayout->addWidget(error);connect(doc,&QPdfDocument::statusChanged,error,[doc,error](QPdfDocument::Status status){if(status==QPdfDocument::Status::Error)error->setText("This PDF could not be previewed. Save it to open in your preferred reader.");});if(doc->status()==QPdfDocument::Status::Error)error->setText("This PDF could not be previewed. You can still save it.");}else if(QStringList{"image/png","image/jpeg","image/gif","image/webp"}.contains(mime)){QImage image=QImage::fromData(bytes);auto*scroll=new QScrollArea;scroll->setWidgetResizable(true);auto*picture=new QLabel;picture->setAlignment(Qt::AlignCenter);if(image.isNull())picture->setText("Image could not be previewed.");else picture->setPixmap(QPixmap::fromImage(image.scaled(1100,1800,Qt::KeepAspectRatio,Qt::SmoothTransformation)));scroll->setWidget(picture);attachmentLayout->addWidget(scroll,1);}else if(mime.startsWith("text/")||mime=="application/json"){auto*text=new QPlainTextEdit;text->setReadOnly(true);text->setPlainText(QString::fromUtf8(bytes.left(2*1024*1024)));attachmentLayout->addWidget(text,1);if(bytes.size()>2*1024*1024)attachmentLayout->addWidget(label("Preview shows the first 2 MB. Save to read the full file.","muted"));}else{attachmentLayout->addWidget(label("Preview is not available for this file type. Use Save to download it."));attachmentLayout->addStretch();}pages->setCurrentWidget(attachmentPage);notify("Attachment · "+account);}

void OmadashWindow::markUnread(){if(pages->currentIndex()!=0&&pages->currentIndex()!=1)return;int ti=pages->currentIndex()==1?threadIndex:inbox->currentItem()?inbox->currentItem()->data(Qt::UserRole).toInt():-1;if(ti<0||ti>=store.threads.size())return;auto t=store.threads[ti].toObject();bool reader=pages->currentIndex()==1,unread=reader||!t["unread"].toBool();if(live){liveAction(unread?"unread":"read");return;}t["unread"]=unread;store.threads[ti]=t;if(reader)back();refreshInbox();save();}

void OmadashWindow::setAccountImages(const QString&id,bool enabled){externalImages[id]=enabled;if(persistPreferences){QString path=QCoreApplication::applicationDirPath()+"/../.state";QDir().mkpath(path);QSettings settings(path+"/image-preferences.ini",QSettings::IniFormat);settings.setValue(QString::fromLatin1(QUrl::toPercentEncoding(id)),enabled);settings.sync();if(settings.status()!=QSettings::NoError)notify("Image preference changed for this session, but could not be saved.");}if(account==id&&pages->currentIndex()==1){buildReader();selectMessage(messageIndex);}}
